-- NovaID Phase 2 normalized PostgreSQL identity core.
CREATE TABLE novaid_tenants (tenant_id uuid PRIMARY KEY, name text NOT NULL, status text NOT NULL CHECK (status IN ('ACTIVE','SUSPENDED','DISABLED')), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, version integer NOT NULL DEFAULT 1);
CREATE TABLE novaid_identities (identity_id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES novaid_tenants, normalized_email text NOT NULL, status text NOT NULL CHECK (status IN ('PENDING_VERIFICATION','ACTIVE','LOCKED','SUSPENDED','DISABLED','DELETED')), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, version integer NOT NULL DEFAULT 1, security_version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id, normalized_email));
CREATE INDEX ix_novaid_identity_tenant ON novaid_identities(tenant_id);
CREATE TABLE novaid_tenant_memberships (membership_id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES novaid_tenants, identity_id uuid NOT NULL REFERENCES novaid_identities, role text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,identity_id));
CREATE TABLE novaid_credentials (credential_id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES novaid_tenants, identity_id uuid NOT NULL REFERENCES novaid_identities, kind text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, version integer NOT NULL DEFAULT 1);
CREATE TABLE novaid_password_credentials (credential_id uuid PRIMARY KEY REFERENCES novaid_credentials, password_hash text NOT NULL, algorithm_version text NOT NULL, expires_at timestamptz, compromised_at timestamptz);
CREATE TABLE novaid_otp_challenges (challenge_id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES novaid_tenants, identity_id uuid NOT NULL REFERENCES novaid_identities, purpose text NOT NULL, destination_reference text NOT NULL, secret_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz, attempt_count integer NOT NULL DEFAULT 0, maximum_attempts integer NOT NULL, status text NOT NULL, correlation_id uuid NOT NULL, CHECK(expires_at>created_at));
CREATE INDEX ix_novaid_otp_expiry ON novaid_otp_challenges(tenant_id,expires_at,status);
CREATE TABLE novaid_authentication_sessions (session_id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES novaid_tenants, identity_id uuid NOT NULL REFERENCES novaid_identities, authentication_time timestamptz NOT NULL, authentication_strength text NOT NULL, credential_id uuid REFERENCES novaid_credentials, device_reference text, client_reference text, risk_score numeric NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, revocation_reason text, version integer NOT NULL DEFAULT 1, CHECK(expires_at>created_at));
CREATE INDEX ix_novaid_session_tenant_identity ON novaid_authentication_sessions(tenant_id,identity_id,status);
CREATE TABLE novaid_refresh_token_families (family_id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES novaid_authentication_sessions, identity_id uuid NOT NULL REFERENCES novaid_identities, tenant_id uuid NOT NULL REFERENCES novaid_tenants, status text NOT NULL, created_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, version integer NOT NULL DEFAULT 1);
CREATE TABLE novaid_refresh_tokens (token_id uuid PRIMARY KEY, family_id uuid NOT NULL REFERENCES novaid_refresh_token_families, session_id uuid NOT NULL REFERENCES novaid_authentication_sessions, identity_id uuid NOT NULL REFERENCES novaid_identities, tenant_id uuid NOT NULL REFERENCES novaid_tenants, token_hash text NOT NULL UNIQUE, parent_token_id uuid REFERENCES novaid_refresh_tokens, issued_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz, revoked_at timestamptz, replacement_token_id uuid, status text NOT NULL CHECK(status IN ('ACTIVE','USED','REVOKED','EXPIRED','REPLAYED')));
CREATE INDEX ix_novaid_refresh_family ON novaid_refresh_tokens(family_id,status);
CREATE TABLE novaid_authentication_attempts (attempt_id uuid PRIMARY KEY, identity_id uuid, tenant_id uuid NOT NULL REFERENCES novaid_tenants, credential_type text NOT NULL, result text NOT NULL, reason_code text NOT NULL, occurred_at timestamptz NOT NULL, correlation_id uuid NOT NULL);
CREATE TABLE novaid_identity_risk_states (identity_id uuid NOT NULL REFERENCES novaid_identities, tenant_id uuid NOT NULL REFERENCES novaid_tenants, risk_score numeric NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, version integer NOT NULL DEFAULT 1, PRIMARY KEY(identity_id,tenant_id));
CREATE TABLE novaid_identity_status_history (transition_id uuid PRIMARY KEY, identity_id uuid NOT NULL REFERENCES novaid_identities, tenant_id uuid NOT NULL REFERENCES novaid_tenants, previous_status text NOT NULL, new_status text NOT NULL, reason_code text NOT NULL, actor_identity_id uuid NOT NULL, correlation_id uuid NOT NULL, occurred_at timestamptz NOT NULL);
CREATE TABLE novaid_security_events (event_id uuid PRIMARY KEY, event_type text NOT NULL, severity text NOT NULL, tenant_id uuid NOT NULL REFERENCES novaid_tenants, actor_identity_id uuid NOT NULL, subject_identity_id uuid NOT NULL, correlation_id uuid NOT NULL, request_id uuid NOT NULL, occurred_at timestamptz NOT NULL, recorded_at timestamptz NOT NULL, outcome text NOT NULL, reason_codes jsonb NOT NULL, metadata jsonb NOT NULL, schema_version integer NOT NULL);
CREATE INDEX ix_novaid_event_correlation ON novaid_security_events(correlation_id,event_type,occurred_at);
CREATE TABLE novaid_idempotency_records (tenant_id uuid NOT NULL REFERENCES novaid_tenants, idempotency_key text NOT NULL, payload_hash text NOT NULL, response_json jsonb NOT NULL, created_at timestamptz NOT NULL, PRIMARY KEY(tenant_id,idempotency_key));
CREATE TABLE novaid_authentication_locks (tenant_id uuid NOT NULL REFERENCES novaid_tenants, identifier_hash text NOT NULL, failure_count integer NOT NULL, window_started_at timestamptz NOT NULL, locked_until timestamptz, updated_at timestamptz NOT NULL, PRIMARY KEY(tenant_id,identifier_hash));
